七、外國人或旅外僑民授權第三人辦理土地登記，該授權書經我駐外館處驗證。
八、大陸地區人民或香港、澳門居民授權第三人辦理土地登記，該授權書經行政院設立或指定之機構或委託之民間團體驗證。
