    isPaid: true,
    detail: `【全國法規原文】
第一項：稅捐之核課期間，依下列規定：
一、依法應由納稅義務人申報繳納之稅捐，已在規定期間內申報，且無故意以詐欺或其他不正當方法逃漏稅捐者，其核課期間為五年。
二、依法應由納稅義務人實貼之印花稅，及應由稅捐稽徵機關依稅籍底冊或查得資料核定課徵之稅捐，其核課期間為五年。
三、未於規定期間內申報，或故意以詐欺或其他不正當方法逃漏稅捐者，其核課期間為七年。
第二項：在前項核課期間內，經另發現應徵之稅捐者，仍應依法補徵或並予處罰；在核課期間內未經發現者，以後不得再補稅處罰。
第三項（時效不完成）：核課期間屆滿，有下列情形之一者，時效不完成：
①納稅義務人提起行政救濟尚未終結者，撤銷後1年內不完成。
②因天災事變不可抗力未能作成核定者，妨礙消滅後6個月內不完成。

⚠️ 核課時效：正常申報→5年；逃稅/未申報→7年。
⚠️ §11-1 是「相當擔保品類型」（黃金/公債/銀行存款/土地房屋等），與核課時效無關。`,
