第三項：法院或行政執行分署執行拍賣或交債權人承受之土地、房屋及貨物，應於拍定或承受後五日內通知稅捐稽徵機關，依法核課土地增值稅、地價稅、房屋稅及營業稅，並由法院或行政執行分署代為扣繳。

