民法§758：不動產物權登記是「生效要件」——依法律行為取得物權，非經登記不生效力。

口訣：信託→對抗；物權移轉→生效。

例題：甲以A地設立信託，登記前乙向甲買A地，乙善意不知→乙可對抗信託（因信託未登記）。
